/// Les commandes du plugin, en snake_case : chacune donne une permission `allow-<commande>` (générée dans
/// `permissions/autogenerated`), et `permissions/default.toml` les réunit. Sur iOS, la méthode Swift porte le même
/// nom en camelCase (`regler_theme` → `reglerTheme`). `register_listener` et `remove_listener` sont ce que la page
/// appelle pour écouter les événements du plugin (`clavier`).
const COMMANDES: &[&str] = &["infos", "regler_theme", "capturer_fenetre", "haptique", "partager", "register_listener", "remove_listener"];

fn main() {
    tauri_plugin::Builder::new(COMMANDES).ios_path("ios").build();
}
